cards.solution:
function hitungKata(kalimat) {
  const hasil = new Map();
  for (const kata of kalimat.toLowerCase().split(" ")) {
    hasil.set(kata, (hasil.get(kata) ?? 0) + 1);
  }
  return hasil;
}
for (const [kata, jumlah] of hitungKata("Saya suka kopi saya suka teh")) {
  console.log(`${kata}: ${jumlah}`);
}
